package api

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
)

// This file and the *_sql.go files are the API package's database access
// layer. Fixed-shape statements are generated by sqlc from
// internal/store/queries (identity.sql, policy.sql, api_hosts.sql,
// api_catalogs.sql) and wrapped here to convert between the sqlc column types
// and the protobuf messages. The statements below stay hand-written:
//
//   - "UPDATE console_users SET manual_roles=", "INSERT INTO join_tokens(" and
//     "INSERT INTO policy_versions(" are matched by their exact SQL text prefix
//     in audit_committed_targets_test.go; sqlc prepends a "-- name:" comment to
//     every statement, which would change that prefix.
//   - The host, catalog and preview statements are built with optional
//     suffixes (FOR UPDATE, a current-version filter) or take a duration as
//     text for an interval cast, so their text is composed at run time.
//   - LISTEN takes an identifier and LOCK TABLE a table list, neither of which
//     can be a bind parameter.
//
// The q argument is a pool or a transaction.

func timestamptz(t time.Time) pgtype.Timestamptz { return pgtype.Timestamptz{Time: t, Valid: true} }

// setUserRoles replaces the manual roles of a user at an expected revision and
// reports the number of rows changed.
func setUserRoles(ctx context.Context, q querier, userID string, revision int64, roles []string) (int64, error) {
	tag, err := q.Exec(ctx, "UPDATE console_users SET manual_roles=$3,revision=revision+1 WHERE user_id=$1 AND revision=$2", userID, revision, roles)
	return tag.RowsAffected(), err
}

// insertJoinToken stores a new join token hash.
func insertJoinToken(ctx context.Context, q querier, id string, tokenHash []byte, uses int64, expires time.Time) error {
	_, err := q.Exec(ctx, "INSERT INTO join_tokens(token_id,token_hash,max_uses,expires_at) VALUES ($1,$2,$3,$4)", id, tokenHash, uses, expires)
	return err
}

// insertInitialPolicy stores version 1 unless a policy already exists.
func insertInitialPolicy(ctx context.Context, q querier, rules []byte) error {
	_, err := q.Exec(ctx, "INSERT INTO policy_versions(version,rules,created_by,reason) VALUES (1,$1,'system','initial defaults') ON CONFLICT DO NOTHING", rules)
	return err
}

// insertPolicyVersion stores the next policy version. rolledBackFrom is nil or
// the uint64 version restored by a rollback.
func insertPolicyVersion(ctx context.Context, q querier, version uint64, rules []byte, actor, reason string, rolledBackFrom any) error {
	_, err := q.Exec(ctx, "INSERT INTO policy_versions(version,rules,created_by,reason,rolled_back_from) VALUES ($1,$2,$3,$4,$5)", version, rules, actor, reason, rolledBackFrom)
	return err
}

// listenPolicy subscribes a dedicated connection to policy change notifications.
func listenPolicy(ctx context.Context, conn *pgx.Conn) error {
	_, err := conn.Exec(ctx, "LISTEN "+PolicyChannel)
	return err
}

// lockPolicyInputs blocks concurrent writes to the tables read by the policy
// snapshot until the transaction ends.
func lockPolicyInputs(ctx context.Context, q querier) error {
	_, err := q.Exec(ctx, "LOCK TABLE console_users,service_accounts,role_mapping_state,role_mappings,hosts,catalog_versions IN SHARE MODE")
	return err
}
